from pathlib import Path
import re

css_path=Path('assets/styles.css')
s=css_path.read_text(encoding='utf-8')
marker='AgentenIndex v8.0 — Modern Light System'
if marker not in s:
    s += "\n\n/* =========================================================\n   AgentenIndex v8.0 — Modern Light System\n   Sitewide visual layer. Keeps content, URLs and SEO markup.\n   ========================================================= */\n\n:root{\n  --bg:#f7f9fc;\n  --paper:#ffffff;\n  --paper2:#f4f7fb;\n  --ink:#0b1739;\n  --muted:#66728a;\n  --line:#e3e9f2;\n  --dark:#0b1739;\n  --accent:#1769ff;\n  --accent2:#eaf2ff;\n  --ok:#078e75;\n  --warn:#9a762d;\n  --r:22px;\n  --shadow:0 22px 65px rgba(30,55,90,.09);\n  --max:1200px;\n}\n\nhtml{background:var(--bg)}\nbody{\n  background:\n    radial-gradient(circle at 8% 0%,rgba(226,244,237,.7),transparent 20%),\n    radial-gradient(circle at 94% 4%,rgba(230,239,255,.78),transparent 22%),\n    var(--bg);\n  color:var(--ink);\n  line-height:1.62;\n}\n.container{width:min(calc(100% - 44px),var(--max))}\n.narrow{width:min(calc(100% - 44px),860px)}\n.eyebrow,.kicker{color:#1764dc}\nh1,h2,h3{color:var(--ink)}\np{color:inherit}\n\n/* top status + floating header */\n.topnote{\n  background:rgba(255,255,255,.72);\n  color:#6f7990;\n  border-bottom:1px solid rgba(228,234,243,.82);\n}\n.topnote .container{padding:6px 0}\n.site-header{\n  position:sticky;\n  top:0;\n  z-index:30;\n  background:rgba(247,249,252,.76);\n  backdrop-filter:blur(20px);\n  border-bottom:0;\n  padding:8px 0;\n}\n.header{\n  height:64px;\n  grid-template-columns:auto 1fr auto;\n  padding:0 14px;\n  background:rgba(255,255,255,.94);\n  border:1px solid rgba(225,232,242,.96);\n  border-radius:20px;\n  box-shadow:0 8px 30px rgba(34,61,98,.055);\n}\n.brand{font-weight:860}\n.brandlogo{width:34px;height:34px;flex-basis:34px;border-radius:10px}\n.brand .brand-main{color:#0b1739}\n.brand .brand-accent{color:#9a762d}\n.nav{gap:19px}\n.nav a,.github{color:#46536d;font-size:.82rem;font-weight:720}\n.nav a:hover,.github:hover{color:#1769ff}\n.nav a.nav-check{\n  background:linear-gradient(135deg,#1769ff,#0b86ff);\n  color:#fff;\n  border-radius:12px;\n  padding:10px 14px;\n  box-shadow:0 8px 24px rgba(23,105,255,.18);\n}\n.nav a.nav-check:hover{background:linear-gradient(135deg,#125be2,#0877e9);color:#fff}\n.menu{\n  border:1px solid #e1e7f0;\n  background:#f7f9fc;\n  color:#26334f;\n  border-radius:11px;\n}\n\n/* shared buttons */\n.btn{\n  border-radius:12px;\n  font-weight:820;\n  transition:transform .16s ease,box-shadow .16s ease;\n}\n.btn:hover{transform:translateY(-1px)}\n.btn.primary{\n  background:linear-gradient(135deg,#1769ff,#0d87ff);\n  color:#fff;\n  box-shadow:0 10px 28px rgba(23,105,255,.18);\n}\n.btn.secondary{\n  border:1px solid #dfe6f0;\n  background:#fff;\n  color:#34415b;\n}\n.searchbox input,\n.filter-field select{\n  border-color:#dde5ef;\n  box-shadow:0 6px 20px rgba(34,61,98,.035);\n}\n.searchbox button,\n.v73index-search button{\n  background:linear-gradient(135deg,#1769ff,#0d87ff)!important;\n  color:#fff!important;\n}\n\n/* generic page surfaces */\n.hero,.subhero,.section,.article{background:transparent}\n.subhero{\n  padding:46px 0 34px;\n  border-bottom:0;\n}\n.subhero .container{\n  padding:38px 40px;\n  border:1px solid #e5ebf3;\n  border-radius:28px;\n  background:\n    radial-gradient(circle at 88% 20%,rgba(77,139,255,.11),transparent 26%),\n    radial-gradient(circle at 7% 94%,rgba(28,184,148,.08),transparent 22%),\n    #fff;\n  box-shadow:0 18px 55px rgba(35,61,96,.055);\n}\n.subhero h1{letter-spacing:-.06em}\n.lead{color:#5f6b83}\n.section.alt{\n  background:linear-gradient(180deg,#f5f9ff,#f9fbfe);\n  border-block:1px solid #e6ecf5;\n}\n.card,.soft-card,.filter-chip,.ref-item,.decision-card,.key-points,.compare-wrap,.deep-table{\n  border-color:#e3e9f2!important;\n  background:#fff!important;\n  box-shadow:0 9px 28px rgba(34,61,98,.035);\n}\n.card,.soft-card,.ref-item,.decision-card,.key-points{border-radius:20px}\n.pill,.term-chip,.source-badge{\n  background:#f5f8fc;\n  border-color:#e4eaf2;\n  color:#536078;\n}\n.answerbox{\n  background:linear-gradient(135deg,#eef6ff,#f8fbff);\n  border-color:#dfeaf8;\n  border-radius:20px;\n  box-shadow:0 10px 30px rgba(34,61,98,.04);\n}\n.answerbox strong{color:#1764dc}\n.editorial-note,.transparency,blockquote,.article blockquote{\n  border-left-color:#1769ff!important;\n  background:linear-gradient(135deg,#f1f6ff,#fbfdff)!important;\n}\n.callout{\n  background:linear-gradient(135deg,#edf5ff,#f2fbf7)!important;\n  color:#17223e!important;\n  border:1px solid #dce8f7;\n  box-shadow:0 12px 36px rgba(34,61,98,.05);\n}\n.callout h2,.callout h3{color:#0b1739!important}\n.callout p{color:#5f6b82!important}\n.callout a{color:#1769ff!important}\n\n/* article system */\n.article{padding:56px 0 82px}\n.article-grid{grid-template-columns:minmax(0,800px) 286px;gap:64px}\n.article p,.article li{color:#3f4d66}\n.article .lede{color:#536078}\n.breadcrumbs{color:#748097}\n.toc{\n  top:104px;\n  background:rgba(255,255,255,.92);\n  border:1px solid #e2e8f1;\n  border-radius:18px;\n  box-shadow:0 12px 34px rgba(35,60,96,.055);\n}\n.toc a{color:#5b6880}\n.toc a:hover{color:#1769ff}\n.factbox{\n  gap:8px;\n  background:transparent;\n  border:0;\n  overflow:visible;\n}\n.fact{\n  border:1px solid #e4eaf2;\n  border-radius:14px;\n  background:#f9fbfe;\n}\n.fact small{color:#7a8598}\n.compare-wrap{border-radius:18px}\n.compare th,.deep-table th{background:#f1f6fc!important;color:#34415a}\n.compare td,.deep-table td{border-color:#e6ebf3!important}\n.flow-node,.concept-map div,.mini-diagram span{\n  border-color:#e2e9f2;\n  border-radius:15px;\n  box-shadow:0 7px 22px rgba(34,61,98,.03);\n}\n.icon{\n  background:#edf5ff;\n  color:#1764dc;\n}\n\n/* home hero */\n.v73home-hero{\n  padding:42px 0 34px;\n  background:transparent;\n}\n.v73home-hero-grid{\n  grid-template-columns:minmax(0,1.04fr) minmax(400px,.96fr);\n  gap:52px;\n  padding:52px;\n  border:1px solid #e5ebf3;\n  border-radius:34px;\n  background:\n    radial-gradient(circle at 84% 14%,rgba(54,128,255,.12),transparent 26%),\n    radial-gradient(circle at 14% 92%,rgba(24,185,147,.08),transparent 24%),\n    linear-gradient(135deg,#fff 0%,#fbfdff 65%,#f8fbff 100%);\n  box-shadow:0 22px 70px rgba(34,61,98,.065);\n}\n.v73home-copy h1{\n  font-size:clamp(3.9rem,7vw,6.8rem);\n  color:#0b1739;\n}\n.v73home-copy h1 span{\n  color:transparent;\n  background:linear-gradient(90deg,#1769ff,#0b87e9 52%,#00a98f);\n  -webkit-background-clip:text;\n  background-clip:text;\n}\n.v73home-lead{color:#59667f}\n.v73home-proof{color:#68758c}\n.v73home-proof span{\n  padding:7px 10px;\n  background:rgba(255,255,255,.72);\n  border:1px solid #e5eaf2;\n  border-radius:999px;\n}\n\n/* ecosystem becomes a bright product panel */\n.v73eco{\n  color:#14203b;\n  background:rgba(255,255,255,.93);\n  border:1px solid #e1e8f2;\n  box-shadow:0 22px 60px rgba(32,59,96,.095);\n}\n.v73eco:before{\n  content:\"\";\n  position:absolute;\n  inset:0;\n  pointer-events:none;\n  background:\n    radial-gradient(circle at 80% 28%,rgba(80,133,255,.12),transparent 22%),\n    radial-gradient(circle at 24% 74%,rgba(25,183,148,.09),transparent 21%);\n}\n.v73eco-head,.v73eco-map,.v73eco>p{position:relative;z-index:1}\n.v73eco-head span{color:#1764dc}\n.v73eco-head small{color:#7c879a}\n.v73eco-ring{border-color:rgba(70,123,216,.18)}\n.v73eco-core{\n  background:linear-gradient(145deg,#1769ff,#0b87e9);\n  color:#fff;\n  box-shadow:0 0 0 12px rgba(23,105,255,.06),0 18px 45px rgba(23,105,255,.18);\n}\n.v73eco-node{\n  background:rgba(255,255,255,.94);\n  border-color:#e1e7f0;\n  box-shadow:0 8px 25px rgba(35,61,96,.055);\n}\n.v73eco-node i{color:#1764dc}\n.v73eco-node b{color:#1c2944}\n.v73eco-node small{color:#7b869a}\n.v73eco>p{\n  color:#68748a;\n  border-top-color:#e6ebf3;\n}\n\n/* stats become cards */\n.v73stats{\n  background:transparent;\n  border:0;\n  padding:12px 0 8px;\n}\n.v73stats-grid{gap:10px}\n.v73stats-grid>a{\n  padding:19px 21px;\n  background:rgba(255,255,255,.86);\n  border:1px solid #e4eaf2!important;\n  border-radius:18px;\n  box-shadow:0 8px 26px rgba(34,61,98,.035);\n}\n.v73stats-grid strong{color:#0b1739}\n.v73stats-grid span{color:#303c56}\n.v73stats-grid small{color:#7a8598}\n\n/* home section headings + content */\n.v73section{padding:80px 0}\n.v73head h2{font-size:clamp(2.5rem,4.6vw,4.4rem);letter-spacing:-.06em}\n.v73head>p{color:#657188}\n.v73center .btn{padding-inline:20px}\n\n/* agent check: no black block */\n.v73check{\n  padding:76px 0;\n  color:#0b1739;\n  background:transparent;\n}\n.v73check-grid{\n  padding:44px;\n  border:1px solid #dfe8f3;\n  border-radius:30px;\n  background:\n    radial-gradient(circle at 88% 15%,rgba(27,189,151,.10),transparent 25%),\n    linear-gradient(135deg,#f8fbff,#f2f8ff 56%,#f6fffb);\n  box-shadow:0 20px 60px rgba(33,60,95,.06);\n}\n.v73check h2{color:#0b1739}\n.v73check p{color:#5e6b82}\n.v73check .kicker{color:#1764dc}\n.v73check-proof{color:#65728a}\n.v73check-proof span{\n  background:#fff;\n  border:1px solid #e3e9f2;\n  padding:7px 9px;\n  border-radius:999px;\n}\n.v73check-grid>div:first-child>a{\n  background:linear-gradient(135deg,#1769ff,#0d87ff);\n  color:#fff;\n  border-radius:12px;\n  box-shadow:0 10px 28px rgba(23,105,255,.18);\n}\n.v73result{\n  background:#fff;\n  border:1px solid #e1e8f1;\n  box-shadow:0 14px 38px rgba(35,61,96,.06);\n}\n.v73result>small{color:#7d879a}\n.v73result h3{color:#1764dc}\n.v73result>div{border-color:#edf0f5}\n.v73result>div span,.v73result>div b{color:#3c4962}\n.v73result i{background:#eef1f6}\n.v73result em{background:linear-gradient(90deg,#1769ff,#00ad92)}\n.v73result footer{background:#f5f8fc}\n.v73result footer span,.v73result footer small{color:#718096}\n.v73result footer b{color:#1764dc}\n\n/* knowledge + audience + method */\n.v73knowledge{\n  background:linear-gradient(180deg,#f4f9ff,#f9fbfe);\n  border-block:1px solid #e5ecf5;\n}\n.v73knowledge-lead,.v73knowledge-list>a{\n  border-color:#e2e9f2;\n  box-shadow:0 9px 28px rgba(34,61,98,.035);\n}\n.v73knowledge-lead span,.v73knowledge-list span{color:#1764dc}\n.v73knowledge-list b{color:#1769ff}\n.v73audience>a{\n  border-color:#e2e8f1;\n  box-shadow:0 10px 30px rgba(34,61,98,.04);\n}\n.v73audience>a.dark{\n  background:\n    radial-gradient(circle at 88% 22%,rgba(119,86,225,.12),transparent 25%),\n    linear-gradient(145deg,#fbf9ff,#f4f0ff);\n  color:#0b1739;\n  border-color:#e5def7;\n}\n.v73audience>a.dark p:not(.kicker){color:#626e86}\n.v73audience>a.dark .kicker{color:#7041d8}\n.v73method{\n  padding:80px 0;\n  background:linear-gradient(180deg,#f7fafc,#f2f6fa);\n  border-top:1px solid #e5ebf2;\n}\n.v73method-grid{\n  padding:38px;\n  background:#fff;\n  border:1px solid #e3e9f2;\n  border-radius:28px;\n  box-shadow:0 16px 48px rgba(34,61,98,.05);\n}\n.v73method-grid>div:last-child>div{border-color:#e7ebf1}\n.v73method-grid span{color:#1764dc}\n.v73method-grid p{color:#69758b}\n\n/* agent index hero */\n.v73agentindex-hero{\n  padding:42px 0 30px;\n  background:transparent;\n  border-bottom:0;\n}\n.v73agentindex-grid{\n  padding:42px;\n  border:1px solid #e4eaf3;\n  border-radius:30px;\n  background:\n    radial-gradient(circle at 88% 18%,rgba(64,130,255,.11),transparent 25%),\n    #fff;\n  box-shadow:0 18px 55px rgba(34,61,98,.055);\n}\n.v73agentindex-side{\n  color:#0b1739;\n  background:linear-gradient(145deg,#f4f8ff,#f1fbf8);\n  border:1px solid #dfe8f3;\n  box-shadow:0 12px 36px rgba(34,61,98,.05);\n}\n.v73agentindex-side>small{color:#1764dc}\n.v73agentindex-side>strong{color:#1769ff}\n.v73agentindex-side>span{color:#5f6b82}\n.v73agentindex-side>div{background:#fff;border:1px solid #e4eaf2}\n.v73agentindex-side p{color:#788398}\n.v73index-filterpanel{\n  border:1px solid #e1e8f1!important;\n  box-shadow:0 10px 30px rgba(34,61,98,.045)!important;\n}\n.v73index-filterchip:hover{border-color:#aac4f4!important}\n\n/* individual AgentenProfil hero */\n.v7p-hero{\n  padding:38px 0 28px;\n  background:transparent;\n  border-bottom:0;\n}\n.v7p-hero-grid{\n  padding:42px;\n  border:1px solid #e4eaf3;\n  border-radius:30px;\n  background:\n    radial-gradient(circle at 88% 16%,rgba(70,133,255,.11),transparent 25%),\n    radial-gradient(circle at 8% 94%,rgba(23,182,148,.07),transparent 22%),\n    #fff;\n  box-shadow:0 18px 55px rgba(34,61,98,.055);\n}\n.v7p-breadcrumbs{color:#758197}\n.v7p-status{\n  background:#e9f8ef;\n  color:#1c743c;\n  border-color:#d9efdf;\n}\n.v7p-date{color:#788398}\n.v7p-hero h1{color:#0b1739}\n.v7p-deck{color:#56647c}\n.v7p-tags span{\n  border-color:#e0e7f0;\n  background:#f7f9fc;\n  color:#536077;\n}\n.v7p-passport-card{\n  color:#0b1739;\n  background:\n    radial-gradient(circle at 76% 26%,rgba(66,129,255,.13),transparent 25%),\n    linear-gradient(145deg,#fff,#f5f9ff);\n  border:1px solid #dfe7f2;\n  box-shadow:0 18px 50px rgba(34,61,98,.09);\n}\n.v7p-passport-card:before{\n  background:radial-gradient(circle,rgba(23,105,255,.10),transparent 65%);\n}\n.v7p-passport-label{color:#1764dc}\n.v7p-passport-id{color:#758097}\n.v7p-orbit:before,.v7p-orbit:after{border-color:rgba(70,124,218,.20)}\n.v7p-orbit i{background:#38a9d8;box-shadow:0 0 16px rgba(56,169,216,.45)}\n.v7p-quickfacts>div{border-color:#e5eaf2}\n.v7p-quickfacts dt{color:#7a8598}\n.v7p-quickfacts dd{color:#24314b}\n.v7p-evidence-strip{\n  background:transparent;\n  border-bottom:0;\n  padding:6px 0 14px;\n}\n.v7p-evidence-strip .container{\n  gap:9px;\n}\n.v7p-evidence-strip .container>div{\n  padding:16px 18px;\n  border:1px solid #e4eaf2!important;\n  border-radius:14px;\n  background:#fff;\n  box-shadow:0 7px 22px rgba(34,61,98,.03);\n}\n.v7p-evidence-strip span{color:#7b869a}\n.v7p-direct-answer{\n  border-color:#e2e9f2;\n  background:linear-gradient(135deg,#f3f8ff,#fff);\n}\n.v7p-direct-kicker{color:#1764dc}\n.v7p-fact-grid>div{\n  background:#f7f9fc;\n  border:1px solid #e5eaf2;\n}\n.v7p-fact-grid small{color:#7a8498}\n.v7p-cap-grid>div{\n  color:#15203c;\n  background:linear-gradient(145deg,#f4f8ff,#f5fbf8);\n  border:1px solid #e0e8f1;\n  box-shadow:0 8px 25px rgba(34,61,98,.035);\n}\n.v7p-cap-grid span{color:#758198}\n.v7p-cap-grid b{color:#1764dc}\n.v7p-cap-grid small{color:#5f6c83}\n.v7p-editorial-feature{\n  background:linear-gradient(135deg,#f3f8ff,#fff);\n  border-color:#e0e8f1;\n}\n.v7p-feature-side{border-color:#e2e8f0}\n.passport-v2{\n  background:linear-gradient(135deg,#fff,#f3f8ff)!important;\n  border-color:#e0e8f1!important;\n  box-shadow:0 13px 38px rgba(34,61,98,.05)!important;\n}\n.passport-id{border-color:#e0e7ef;background:#f8faff;color:#526079}\n.passport-grid{background:transparent;border:0;gap:8px;overflow:visible}\n.passport-grid>div{\n  background:#f7f9fc!important;\n  border:1px solid #e5eaf2;\n  border-radius:12px;\n}\n.passport-grid small{color:#7a8598}\n.passport-chip{border-color:#e0e7ef;background:#f5f8fc;color:#536078}\n.v73-profile-cta{\n  color:#0b1739;\n  background:linear-gradient(135deg,#eef6ff,#f2fbf7);\n  border:1px solid #dfe8f2;\n  box-shadow:0 14px 42px rgba(34,61,98,.05);\n}\n.v73-profile-cta h2{color:#0b1739}\n.v73-profile-cta p:not(.kicker){color:#617087}\n.v73-profile-cta .kicker{color:#1764dc}\n.v73-profile-cta>a{\n  background:linear-gradient(135deg,#1769ff,#0d87ff);\n  color:#fff;\n  border-radius:12px;\n}\n\n/* generic AgentenCheck CTA used on several pages */\n.agentencheck-cta{\n  color:#0b1739;\n  background:\n    radial-gradient(circle at 88% 18%,rgba(28,187,150,.09),transparent 24%),\n    linear-gradient(135deg,#f4f9ff,#f4fbf8);\n  border:1px solid #dfe8f2;\n  box-shadow:0 15px 45px rgba(34,61,98,.055);\n}\n.agentencheck-cta:after{opacity:.025}\n.agentencheck-cta .kicker{color:#1764dc}\n.agentencheck-cta h2{color:#0b1739}\n.agentencheck-cta p{color:#5e6b82}\n.agentencheck-cta .btn,\n.agentencheck-cta>a{\n  background:linear-gradient(135deg,#1769ff,#0d87ff);\n  color:#fff;\n}\n\n/* modern footer */\n.footer{\n  background:#fff;\n  color:#17223d;\n  border-top:1px solid #e2e8f1;\n  padding:44px 0 24px;\n}\n.footer p{color:#738096}\n.footer-links a{color:#536078}\n.footer-links a:hover{color:#1769ff}\n.footer .brand .brand-main{color:#0b1739}\n.footer .brand .brand-accent{color:#9a762d}\n.foot-bottom{\n  border-top-color:#e6ebf2;\n  color:#7a8598;\n}\n.legal-links a{color:#66728a}\n.footer-note{color:#8790a1}\n\n/* mobile */\n@media(max-width:1040px){\n  .v73home-hero-grid,.v73check-grid,.v7p-hero-grid{grid-template-columns:1fr}\n  .v73eco,.v7p-passport-card{max-width:760px}\n}\n@media(max-width:900px){\n  .site-header{padding:6px 0}\n  .header{height:60px}\n  .nav.nav-open{\n    top:68px;\n    background:#fff;\n    border-color:#e0e7f0;\n    border-radius:18px;\n    box-shadow:0 18px 48px rgba(34,61,98,.12);\n  }\n  .v73agentindex-grid{grid-template-columns:1fr}\n  .v73agentindex-side{max-width:none}\n}\n@media(max-width:700px){\n  .container,.narrow{width:min(calc(100% - 28px),var(--max))}\n  .v73home-hero-grid,.v73check-grid,.v73agentindex-grid,.v7p-hero-grid{\n    padding:26px 20px;\n    border-radius:24px;\n  }\n  .v73home-copy h1{font-size:clamp(3rem,15vw,4.7rem)}\n  .v73eco{min-height:450px;padding:20px}\n  .v73stats-grid{grid-template-columns:1fr}\n  .v73stats-grid>a{border:1px solid #e4eaf2!important}\n  .v7p-evidence-strip .container{grid-template-columns:1fr 1fr}\n  .subhero .container{padding:28px 22px;border-radius:24px}\n  .v73method-grid{padding:26px}\n  .footer-grid{grid-template-columns:1fr}\n}\n@media(max-width:520px){\n  .v7p-evidence-strip .container{grid-template-columns:1fr}\n}\n"
css_path.write_text(s,encoding='utf-8')

changed=0
for p in Path('.').rglob('*.html'):
    if '.git' in p.parts:
        continue
    t=p.read_text(encoding='utf-8')
    n=re.sub(r'/assets/styles\.css\?v=[^"\']+', '/assets/styles.css?v=8.0.0', t)
    n=n.replace('<meta name="theme-color" content="#9a7a33"/>','<meta name="theme-color" content="#f7f9fc"/>')
    if n!=t:
        p.write_text(n,encoding='utf-8')
        changed+=1

# validation
assert marker in css_path.read_text(encoding='utf-8')
versions=set()
pages=0
for p in Path('.').rglob('*.html'):
    if '.git' in p.parts or p.as_posix().startswith('design-'):
        continue
    t=p.read_text(encoding='utf-8')
    if '/assets/styles.css?v=8.0.0' in t:
        pages+=1
    for m in re.finditer(r'/assets/styles\.css\?v=([^"\']+)',t):
        versions.add(m.group(1))
assert versions=={'8.0.0'},versions
assert pages>=140,pages

home=Path('index.html').read_text(encoding='utf-8')
idx=Path('agenten/index.html').read_text(encoding='utf-8')
profile=Path('agenten/claude-code/index.html').read_text(encoding='utf-8')
assert 'ai-agent-card' in home
assert 'modern-agent-grid' in idx
assert 'v7p-passport-card' in profile
print('V8_ROLLOUT_READY', 'html_changed',changed,'production_pages',pages)
